style.css:
@-moz-document url-prefix("https://") {
html, body {
    cursor: url("https://cur.cursors-4u.net/nature/nat-9/nat833.cur"), auto !important;
  }

  body::after {
    content: '';
    position: fixed;
    top: 12px;
    right: 12px;
    width: 34px;
    height: 34px;
    background-image: url("https://cur.cursors-4u.net/cursor.png");
    background-size: contain;
    background-repeat: no-repeat;
    z-index: 9999;
    opacity: 0.7;
    transition: opacity 0.3s ease;
  }

  body:hover::after {
    opacity: 1;
  }
}
